}

@keyframes browse-record {
  0% {
    opacity: 0.58;
    filter: brightness(0.72);
    transform: translateY(2.2rem) rotateX(-22deg) scale(0.94);
  }

  42%,
  58% {
    opacity: 1;
    filter: brightness(1);
    transform: translateY(0) rotateX(0) scale(1);
  }

  100% {
    opacity: 0.64;
    filter: brightness(0.8);
    transform: translateY(-1.4rem) rotateX(18deg) scale(0.96);
  }
}

@media (prefers-reduced-motion: reduce) {
  .record-item {
    animation: none;
  }

  .album-sleeve,
  .album-caption {
    transition: none;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .prototype-switcher,
  .album-caption {
    backdrop-filter: none;
  }
}

content.text:
.variant-shell {
  --catalog-ink: oklch(0.2 0.01 70);
  --catalog-paper: oklch(0.95 0.015 80);
  box-sizing: border-box;
  height: 100dvh;
  min-width: 64rem;
  overflow: hidden;
  color: var(--catalog-ink);
}

.variant-shell *,
.variant-shell *::before,
.variant-shell *::after {
  box-sizing: border-box;
}

.album-lanes {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  height: 100%;
  min-height: 0;
}

.catalog-lane {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  perspective: 70rem;
}

.lane-label {
  position: absolute;
  z-index: 3;
  inset: 0.75rem 0.75rem auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  pointer-events: none;
}

.record-list {
  height: 100%;
  margin: 0;
  padding: 20vh 0.75rem 38vh;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
  list-style: none;
  scroll-snap-type: y mandatory;
}

.record-list::-webkit-scrollbar {
  display: none;
}

.record-list:focus-visible {
  outline: 0.15rem solid currentColor;
  outline-offset: -0.2rem;
}

.record-item {
  position: relative;
  margin-block-start: -8.25rem;
  scroll-snap-align: center;
  transform-origin: center bottom;
  animation: browse-record linear both;
  animation-timeline: view(block);
  animation-range: entry 5% exit 95%;
}

.record-item:first-child {
  margin-block-start: 0;
}

.album-sleeve {
  position: relative;
  display: block;
  color: inherit;
  text-decoration: none;
  transform-origin: center bottom;
  transition:
    transform 180ms cubic-bezier(0.16, 1, 0.3, 1),
    filter 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.album-sleeve:hover,
.album-sleeve:focus-visible {
  z-index: 4;
  transform: translateY(-0.65rem) scale(1.025);
}

.album-sleeve:focus-visible {
  outline: 0.18rem solid currentColor;
  outline-offset: 0.2rem;
}

.album-figure {
  position: relative;
  aspect-ratio: 1;
  margin: 0;
  overflow: hidden;
  background: var(--catalog-paper);
}

.album-art {
  object-fit: cover;
}

.album-caption {
  position: absolute;
  inset: auto 0 0;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.1rem 0.75rem;
  padding: 0.7rem;
  background: color-mix(in oklch, var(--catalog-ink) 88%, transparent);
  color: var(--catalog-paper);
  transform: translateY(105%);
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.album-caption > :nth-child(2) {
  grid-column: 1;
}

.album-caption > :last-child {
  grid-row: 1 / span 2;
  grid-column: 2;
  align-self: end;
}

.album-sleeve:hover .album-caption,
.album-sleeve:focus-visible .album-caption {
  transform: translateY(0);
}

.prototype-switcher {
  position: fixed;
  z-index: 30;
  inset: auto auto 1rem 50%;
  padding: 0.4rem;
  border: 0.08rem solid oklch(0.22 0.01 260 / 0.32);
  border-radius: 999rem;
  background: oklch(0.96 0.008 260 / 0.96);
  color: oklch(0.18 0.01 260);
  box-shadow: 0 0.75rem 2.5rem oklch(0.02 0 0 / 0.35);
  transform: translateX(-50%);
  backdrop-filter: blur(1rem);
}

.prototype-switcher .astryx-button {
  min-width: 4.5rem;
  border-radius: 999rem;
}

.prototype-switcher .astryx-text {
  white-space: nowrap;
}

.catalog-empty {
  display: grid;
  min-height: 100dvh;
  place-content: center;
  gap: 0.75rem;
  padding: 2rem;
  text-align: center;
}

