  color: var(--catalog-ink);
}

.gallery-footer {
  display: flex;
  min-height: 2.8rem;
  align-items: center;
  justify-content: flex-end;
  padding-inline: 2rem;
  border-top: 0.08rem solid var(--gallery-line);
}

@keyframes browse-record {
  0% {
    opacity: 0.58;
    filter: brightness(0.72);
    transform: translateY(2.2rem) rotateX(-22deg) scale(0.94);
  }

  42%,
  58% {
    opacity: 1;
    filter: brightness(1);
    transform: translateY(0) rotateX(0) scale(1);
  }

  100% {
    opacity: 0.64;
    filter: brightness(0.8);
    transform: translateY(-1.4rem) rotateX(18deg) scale(0.96);
  }
}

@media (prefers-reduced-motion: reduce) {
  .record-item {
    animation: none;
  }

  .album-sleeve,
  .album-caption {
    transition: none;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .prototype-switcher,
  .album-caption {
    backdrop-filter: none;
  }
}

