  3	import { useCallback, useEffect } from "react"
  4	import { useRouter } from "next/navigation"
  5	import { Button } from "@astryxdesign/core/Button"
  6	import { HStack } from "@astryxdesign/core/HStack"
  7	import { Text } from "@astryxdesign/core/Text"
  8	
  9	import type { VariantKey } from "./types"
 10	
 11	const variants: { key: VariantKey; name: string }[] = [
 12	  { key: "A", name: "Record shop" },
 13	  { key: "B", name: "Cover flow" },
 14	  { key: "C", name: "Archive index" },
 15	  { key: "D", name: "Pirate radio" },
 16	  { key: "E", name: "Listening gallery" },
 17	]
 18	
 19	interface PrototypeSwitcherProps {
 20	  current: VariantKey
 21	  onChange: (variant: VariantKey) => void
 22	}
 23	
 24	export function PrototypeSwitcher({
 25	  current,
 26	  onChange,
 27	}: PrototypeSwitcherProps) {
 28	  const router = useRouter()
 29	  const currentIndex = variants.findIndex(({ key }) => key === current)
 30	
 31	  const select = useCallback(
 32	    (offset: number) => {
 33	      const next =
 34	        variants[(currentIndex + offset + variants.length) % variants.length]
 35	      onChange(next.key)
 36	      router.replace(`/?variant=${next.key}`, { scroll: false })
 37	    },
 38	    [currentIndex, onChange, router]
 39	  )
 40	
 41	  useEffect(() => {
 42	    const onKeyDown = (event: KeyboardEvent) => {
 43	      const target = event.target
 44	      if (
 45	        target instanceof HTMLElement &&
 46	        target.matches("input, textarea, [contenteditable='true']")
 47	      ) {
 48	        return
 49	      }
 50	
 51	      if (event.key === "ArrowLeft") select(-1)
 52	      if (event.key === "ArrowRight") select(1)
 53	    }
 54	
 55	    window.addEventListener("keydown", onKeyDown)
 56	    return () => window.removeEventListener("keydown", onKeyDown)
 57	  }, [select])
 58	
 59	  if (process.env.NODE_ENV === "production") return null
 60	
 61	  const active = variants[currentIndex]
 62	
 63	  return (
 64	    <aside className="prototype-switcher" aria-label="Prototype variants">
 65	      <HStack gap={3} vAlign="center">
 66	        <Button label="Prev" variant="secondary" onClick={() => select(-1)} />
 67	        <Text type="code" color="inherit" hasTabularNumbers>
 68	          {active.key} · {active.name}
 69	        </Text>
 70	        <Button label="Next" variant="secondary" onClick={() => select(1)} />
 71	      </HStack>
 72	    </aside>
 73	  )
 74	}
  1	import "server-only"
  2	
  3	import type { AlbumPost } from "@/app/_catalog-prototype/types"
  4	
  5	interface WordPressTerm {
  6	  name: string
  7	  taxonomy: string
  8	}
  9	
 10	interface WordPressMedia {
 11	  alt_text?: string
 12	  source_url?: string
 13	}
 14	
 15	interface WordPressPost {
 16	  id: number
 17	  date: string
 18	  link: string
 19	  title: { rendered: string }
 20	  _embedded?: {
 21	    "wp:featuredmedia"?: WordPressMedia[]
 22	    "wp:term"?: WordPressTerm[][]
 23	  }
 24	}
 25	
 26	const entityMap: Record<string, string> = {
 27	  amp: "&",
 28	  apos: "'",
 29	  hellip: "…",
 30	  nbsp: " ",
 31	  quot: '"',
 32	}
 33	
 34	function decodeEntities(value: string) {
 35	  return value
 36	    .replace(/&#(\d+);/g, (_, code: string) =>
 37	      String.fromCodePoint(Number(code))
 38	    )
 39	    .replace(
 40	      /&([a-z]+);/gi,
 41	      (entity, name: string) => entityMap[name] ?? entity
 42	    )
 43	}
 44	
 45	function apiRoot() {
 46	  const base = process.env.WORDPRESS_BASE_URL?.replace(/\/$/, "")
 47	
 48	  if (!base) throw new Error("WORDPRESS_BASE_URL is missing")
 49	
 50	  return base.includes("/wp-json/wp/v2") ? base : `${base}/wp-json/wp/v2`
 51	}
 52	
 53	function requestHeaders() {
 54	  const username = process.env.WORDPRESS_USERNAME
 55	  const password = process.env.WORDPRESS_APP_PASSWORD
 56	
 57	  if (!username || !password)
 58	    throw new Error("WordPress credentials are missing")
 59	
 60	  return {
 61	    Authorization: `Basic ${Buffer.from(`${username}:${password}`).toString("base64")}`,
 62	  }
 63	}
 64	
 65	async function fetchPage(page: number) {
 66	  const url = URL.parse(`${apiRoot()}/posts`)
 67	
 68	  if (!url) throw new Error("WordPress API URL is invalid")
 69	
 70	  url.searchParams.set("page", String(page))
 71	  url.searchParams.set("per_page", "100")
 72	  url.searchParams.set("_embed", "wp:featuredmedia,wp:term")
 73	  url.searchParams.set("_fields", "id,date,link,title,_links,_embedded")
 74	
 75	  const response = await fetch(url, {
 76	    cache: "no-store",
 77	    headers: requestHeaders(),
 78	    signal: AbortSignal.timeout(15_000),
 79	  })
 80	
 81	  if (!response.ok) throw new Error(`WordPress returned ${response.status}`)
 82	
 83	  return {
 84	    posts: (await response.json()) as WordPressPost[],
 85	    totalPages: Number(response.headers.get("x-wp-totalpages") ?? 1),
 86	  }
 87	}
 88	
 89	export async function getAlbumPosts(): Promise<AlbumPost[]> {
 90	  const first = await fetchPage(1)
 91	  const remaining = await Promise.all(
 92	    Array.from({ length: first.totalPages - 1 }, (_, index) =>
 93	      fetchPage(index + 2)
 94	    )
 95	  )
 96	
 97	  return [first, ...remaining]
 98	    .flatMap(({ posts }) => posts)
 99	    .flatMap((post) => {
100	      const media = post._embedded?.["wp:featuredmedia"]?.[0]
101	      const terms = post._embedded?.["wp:term"]?.flat() ?? []
102	
103	      if (!media?.source_url) return []
104	
105	      const title = decodeEntities(post.title.rendered)
106	      const artist =
107	        terms.find(({ taxonomy }) => taxonomy === "artist")?.name ??
108	        terms.find(({ taxonomy }) => taxonomy === "post_tag")?.name ??
109	        "Unknown artist"
110	
111	      return [
112	        {
113	          id: post.id,
114	          title,
115	          artist: decodeEntities(artist),
116	          genre: decodeEntities(
117	            terms.find(({ taxonomy }) => taxonomy === "genre")?.name ?? "Album"
118	          ),
119	          year: post.date.slice(0, 4),
120	          href: post.link,
121	          imageUrl: media.source_url,
122	          imageAlt: media.alt_text || `${title} album art`,
123	        },
124	      ]
125	    })
126	}

